-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ruRU" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.retail.evoker.augmentation.Name"] = "Icy Veins"
L["rm.retail.evoker.augmentation.Description"] = "Рекомендуется для специализации «Насыщатель»: приоритет Черной мощи по Icy Veins. Черная мощь — один из немногих положительных эффектов, которые игра ещё показывает аддонам в бою в Midnight, поэтому её поддержание там работает. Вне боя: Вздувшаяся чешуя на дружественную цель из группы без неё, Живой жар по врагу. Затем Черная мощь, если её нет или осталось меньше 4 секунд, а также по готовности, если не готово Дыхание эпох; Предвидение; Огненное дыхание; Дрожь земли; Извержение во время Черной мощи или при двух зарядах Взрывной сущности; Лазурный удар; Живой жар. В бою из-за скрытых положительных эффектов пропускаются только зависящие от них шаги. Напоминания: Дыхание эпох и Глубокий вдох (их направляете вы), Смещение равновесия при готовом Огненном дыхании, Пропустить время, когда Огненное дыхание и Дрожь земли восстанавливаются, а также вспомогательные напоминания. Предвидение и Вздувшаяся чешуя применяются на вашу цель: выбор союзника и уровня усиления — за вами."
L["rm.retail.evoker.augmentation.assisted.Name"] = "Боевой помощник Blizzard"
L["rm.retail.evoker.augmentation.assisted.Description"] = "Предложение Боевого помощника Blizzard для специализации «Насыщатель» — альтернатива рекомендуемой встроенной ротации «Насыщатель» от Icy Veins, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Она заново применяет Черную мощь только после того, как та спала, и ждёт, пока вы применяете заклинание или удерживаете усиливаемое заклинание. Напоминания в бою: Дыхание эпох, Глубокий вдох, Смещение равновесия и Пропустить время, а также Подавление, Обсидиановая чешуя, Дар бронзовых драконов и Магический источник, как в других встроенных ротациях пробудителя."
L["rm.retail.evoker.devastation.Name"] = "Боевой помощник Blizzard"
L["rm.retail.evoker.devastation.Description"] = "Рекомендуется для специализации «Опустошитель». Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете заклинание, поддерживаете Дезинтеграцию или удерживаете усиливаемое заклинание, ротация ждёт. Выбор уровня усиления — за вами. Рядом с ним — напоминания: в бою Ярость дракона, Глубокий вдох и Смещение равновесия, Подавление против прерываемого заклинания и Обсидиановая чешуя по готовности, а вне боя Дар бронзовых драконов, если его нет, и Магический источник на дружественную цель в вашей группе. В бою заклинания противников скрыты, поэтому Подавление загорается только там, где игра его показывает; на Retail здоровье скрыто, поэтому момент для Обсидиановой чешуи — на ваше усмотрение."
L["rm.retail.evoker.devastation.guide.Name"] = "Для справки (SimulationCraft и Icy Veins)"
L["rm.retail.evoker.devastation.guide.Description"] = "Только для справки, по умолчанию выключена: оптимальный приоритет «Опустошителя». Срабатывания, восстановление способностей и горение на цели скрыты в бою в Midnight, поэтому этот список не может там работать; читайте его или продублируйте, чтобы поэкспериментировать. Начало боя: Живой жар. Дракомандир (известна Массовая дезинтеграция): Всплеск вечности, Огненное дыхание, Глубокий вдох против двух и более врагов, Дезинтеграция при зарядах Массовой дезинтеграции, Погребальный костер против пяти и более, Дезинтеграция, Живой жар при Выгорании с Прыгучим пламенем, Необузданный огонь при менее чем двух зарядах Взрывной сущности, Лазурный взмах. Ваятель огня: Всплеск вечности, Огненное дыхание, если его горения нет или оно заканчивается, Погребальный костер против пяти и более, Дезинтеграция, Глубокий вдох против четырёх и более, Необузданный огонь, Живой жар при Выгорании с Прыгучим пламенем, Лазурный взмах. Затем Лазурный удар в движении, Живой жар, Лазурный удар. Усиливаемые заклинания против одной цели — на 1-м уровне (Icy Veins). Напоминания: Ярость дракона, Смещение равновесия во время Ярости дракона или при готовом Огненном дыхании, Глубокий вдох для Дракомандира, а также вспомогательные напоминания."
L["rm.retail.evoker.initial.Name"] = "Боевой помощник Blizzard"
L["rm.retail.evoker.initial.Description"] = "Рекомендуется до выбора специализации (пока игра сообщает начальную специализацию пробудителя). Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — общие напоминания всех встроенных ротаций пробудителя, каждое — как только вы знаете соответствующее заклинание. Когда на 10 уровне вы выбираете специализацию, её встроенные ротации вступают в силу."
L["rm.retail.evoker.preservation.Name"] = "Для справки (Icy Veins)"
L["rm.retail.evoker.preservation.Description"] = "Только для справки, по умолчанию выключена. Здоровье союзников, Отголосок, Инверсия, Взрывная сущность и все способности с восстановлением скрыты от аддонов в бою в Midnight, Rotation Master не может выбирать, кого лечить, а у Blizzard нет ротации Боевого помощника для лекарей, поэтому эта встроенная ротация не лечит. Она напоминает о Даре бронзовых драконов и Магическом источнике вне боя, а когда в цели враг, предлагает урон: Огненное дыхание, Дезинтеграция, Живой жар и Лазурный удар в движении. Напоминания о Подавлении и Обсидиановой чешуе — как в других встроенных ротациях пробудителя. Лечение остаётся за вами."
